@@ -1,21 +1,56 @@
 /** Stable, session-independent match identifier for URL routing.
  *
- * Slug = `${cargoId}--${vesselId}`. The double-dash separator is safe
- * because email IDs in demo data use single dashes only (e.g. "demo-cargo-001").
- * Production email IDs are UUIDs or similar — never contain `--`.
+ * Legacy format (item 0): `${cargoId}--${vesselId}` — backward-compatible.
+ * Item-aware format (non-zero item): `${cargoId}::${ci}--${vesselId}::${vi}`.
+ * The `::` separator binds each ID to its item index; `--` separates cargo from vessel.
+ * Both separators are safe: email IDs use single dashes only; `::` never appears in them.
  */

-export function toMatchSlug(cargoId: string, vesselId: string): string {
-  return `${cargoId}--${vesselId}`;
+export function toMatchSlug(
+  cargoId: string,
+  vesselId: string,
+  cargoItemIndex?: number | null,
+  vesselItemIndex?: number | null,
+): string {
+  const ci = cargoItemIndex ?? 0;
+  const vi = vesselItemIndex ?? 0;
+  if (ci === 0 && vi === 0) {
+    return `${cargoId}--${vesselId}`;
+  }
+  return `${cargoId}::${ci}--${vesselId}::${vi}`;
 }

+/** Legacy parser — returns only { cargo_id, vessel_id }. Backward-compatible. */
 export function fromMatchSlug(
   slug: string,
 ): { cargo_id: string; vessel_id: string } | null {
+  const full = fromMatchSlugFull(slug);
+  if (!full) return null;
+  return { cargo_id: full.cargo_id, vessel_id: full.vessel_id };
+}
+
+/** Full parser — includes item indices (0 for legacy slugs). */
+export function fromMatchSlugFull(slug: string): {
+  cargo_id: string;
+  cargo_item_index: number;
+  vessel_id: string;
+  vessel_item_index: number;
+} | null {
   const idx = slug.indexOf('--');
-  if (idx < 1) return null; // no separator or empty cargo_id
-  const cargo_id = slug.slice(0, idx);
-  const vessel_id = slug.slice(idx + 2);
-  if (!vessel_id) return null;
-  return { cargo_id, vessel_id };
+  if (idx < 1) return null;
+  const cargoPart = slug.slice(0, idx);
+  const vesselPart = slug.slice(idx + 2);
+  if (!vesselPart) return null;
+
+  // Support both formats: "id::N" (new) and plain "id" (legacy, item_index=0).
+  const ci = cargoPart.lastIndexOf('::');
+  const cargo_id = ci < 0 ? cargoPart : cargoPart.slice(0, ci);
+  const cargo_item_index = ci < 0 ? 0 : parseInt(cargoPart.slice(ci + 2), 10) || 0;
+
+  const vi = vesselPart.lastIndexOf('::');
+  const vessel_id = vi < 0 ? vesselPart : vesselPart.slice(0, vi);
+  const vessel_item_index = vi < 0 ? 0 : parseInt(vesselPart.slice(vi + 2), 10) || 0;
+
+  if (!cargo_id || !vessel_id) return null;
+  return { cargo_id, cargo_item_index, vessel_id, vessel_item_index };
 }
