new file mode 100644
index 00000000..1301e76c
--- /dev/null
+++ b/lib/migrations/051-matches-item-unique.ts
@@ -0,0 +1,42 @@
+import type { Migration } from "./types";
+
+const migration051: Migration = {
+  version: 51,
+  name: "matches-unique-item-pair",
+  up(db) {
+    // Drop the email-pair unique index from migration 034 (cargo_id, vessel_id, user_id).
+    // It collapsed all items from the same email pair into a single row, losing the
+    // second cargo from a multi-cargo letter. The new index is per item-pair.
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Remove duplicates that share the same item-pair, keeping the earliest row.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, COALESCE(cargo_item_index, 0),
+                 vessel_id, COALESCE(vessel_item_index, 0),
+                 COALESCE(user_id, '')
+      )
+    `);
+
+    // New unique index: one row per (cargo email + item, vessel email + item, user).
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(
+        cargo_id, COALESCE(cargo_item_index, 0),
+        vessel_id, COALESCE(vessel_item_index, 0),
+        COALESCE(user_id, '')
+      )
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
