+import type { Migration } from "./types";
+
+const migration051: Migration = {
+  version: 51,
+  name: "matches-item-unique-constraint",
+  up(db) {
+    // Drop the old email-pair-level unique index (migration 034).
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_cargo_vessel_user`);
+
+    // Remove duplicates at the new item-pair level, keeping the earliest row.
+    db.exec(`
+      DELETE FROM matches
+      WHERE rowid NOT IN (
+        SELECT MIN(rowid) FROM matches
+        GROUP BY cargo_id, COALESCE(cargo_item_index, 0), vessel_id, COALESCE(vessel_item_index, 0), COALESCE(user_id, '')
+      )
+    `);
+
+    // New unique index: one match per (cargo email, cargo item, vessel email, vessel item, user).
+    // Allows a second cargo from the same email to have its own match with the same vessel email.
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_item_pair
+      ON matches(cargo_id, COALESCE(cargo_item_index, 0), vessel_id, COALESCE(vessel_item_index, 0), COALESCE(user_id, ''))
+    `);
+  },
+  down(db) {
+    db.exec(`DROP INDEX IF EXISTS idx_matches_unique_item_pair`);
+    db.exec(`
+      CREATE UNIQUE INDEX IF NOT EXISTS idx_matches_unique_cargo_vessel_user
+      ON matches(cargo_id, vessel_id, COALESCE(user_id, ''))
+    `);
+  },
+};
+
+export default migration051;
